component.script:
"""Elasticsearch -- index, search and delete documents in the organization's Elasticsearch.

One node runs one operation, chosen in the Inspector: SEARCH, INSERT,
CREATE_INDEX, DELETE, LIST_INDICES or DELETE_INDEX. The index name may contain
${field} placeholders, filled from the incoming request_data. The documents,
queries, mappings and settings an operation consumes arrive in request_data.

A misconfigured node raises ValueError before Elasticsearch is touched. An
Elasticsearch failure raises from the client, and a bulk insert that rejects
any document raises too: a document that was not indexed must fail the run,
never be counted as inserted.
"""

import json
import re

import perceivo

_MAX_RESULTS = 1000
# The fields each operation adds to response_data; the artifact carries exactly these.
_RESULT_FIELDS = {
    "SEARCH": ("operation", "index_name", "results", "total", "index_missing"),
    "INSERT": ("operation", "index_name", "insert_count"),
    "CREATE_INDEX": ("operation", "index_name"),
    "DELETE": ("operation", "index_name", "deleted"),
    "LIST_INDICES": ("operation", "index_name", "indices"),
    "DELETE_INDEX": ("operation", "index_name"),
}
_PLACEHOLDER = re.compile(r"\$\{([\w.]+)\}")


def _lookup(data, path: str):
    """Return (True, value) for a dotted path into data, or (False, None)."""
    value = data
    for part in path.split("."):
        if isinstance(value, dict) and part in value:
            value = value[part]
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def _fill(label: str, template: str, data: dict) -> str:
    """Replace each ${path} in template with that value from data, raising on a missing field."""

    def _replace(match):
        found, value = _lookup(data, match.group(1))
        if not found:
            raise ValueError(
                f"{label} refers to ${{{match.group(1)}}}, but the incoming data has no such field."
            )
        return value if isinstance(value, str) else json.dumps(value)

    return _PLACEHOLDER.sub(_replace, template)


def _param(name: str, default: str = "") -> str:
    value = perceivo.params.get(name, default)
    return default if value is None else str(value)


def _result_count() -> int:
    raw = perceivo.params.get("top_k", 10)
    try:
        count = int(raw)
    except (TypeError, ValueError):
        raise ValueError(f"Result Count is {raw!r}. Use a whole number from 1 to {_MAX_RESULTS}.") from None
    if not 1 <= count <= _MAX_RESULTS:
        raise ValueError(f"Result Count is {count}. Use a whole number from 1 to {_MAX_RESULTS}.")
    return count


def _optional_object(data: dict, name: str):
    """request_data[name] when it is an object, None when absent; anything else raises."""
    value = data.get(name)
    if value is None:
        return None
    if not isinstance(value, dict):
        raise ValueError(f"request_data.{name} must be an object, not {type(value).__name__}.")
    return value


def _build_query(data: dict, search_fields: str) -> dict:
    """The query DSL: an explicit query_dsl wins; else query_text over Search Fields; else match_all."""
    explicit = _optional_object(data, "query_dsl")
    if explicit:
        return explicit
    text = data.get("query_text")
    if text is None or str(text).strip() == "":
        return {"match_all": {}}
    query = {"query": str(text)}
    fields = [f.strip() for f in search_fields.split(",") if f.strip()]
    if fields:
        query["fields"] = fields
    return {"multi_match": query}


def _documents(data: dict) -> tuple:
    """Validate INSERT's documents and doc_ids; return (documents, doc_ids or None)."""
    documents = data.get("documents")
    if not isinstance(documents, list) or not documents:
        raise ValueError("INSERT needs a non-empty documents array in request_data.")
    if not all(isinstance(doc, dict) for doc in documents):
        raise ValueError("INSERT needs every item of documents to be an object.")
    doc_ids = data.get("doc_ids")
    if doc_ids is None:
        return documents, None
    if not isinstance(doc_ids, list) or len(doc_ids) != len(documents):
        raise ValueError(
            f"doc_ids must be an array with one id per document ({len(documents)}), "
            "or be left out so Elasticsearch assigns ids."
        )
    return documents, [str(doc_id) for doc_id in doc_ids]


def _hits(response) -> tuple:
    """Return (results, total) from a search response, each hit flattened to id, score and source."""
    block = response.get("hits") or {}
    results = [
        {"id": hit.get("_id"), "score": hit.get("_score"), **(hit.get("_source") or {})}
        for hit in block.get("hits") or []
    ]
    total = block.get("total") or 0
    if isinstance(total, dict):
        total = total.get("value") or 0
    return results, int(total)


@perceivo.agent
async def elasticsearch_agent(input: perceivo.primitives.AgentInput) -> perceivo.primitives.AgentOutput:
    """Run one Elasticsearch operation.

    The JSON artifact carries the operation's result. response_data carries the
    same fields on top of the incoming request_data, less the bulky inputs this
    node consumed (documents, doc_ids, query_text, query_dsl, mappings,
    settings), so downstream nodes keep their context.
    """
    data = input.request_data or {}
    if not isinstance(data, dict):
        raise ValueError(f"request_data must be an object, not {type(data).__name__}.")

    operation = _param("operation", "SEARCH").strip().upper()
    if operation not in _RESULT_FIELDS:
        raise ValueError(f"Operation is {operation!r}. Choose one of: {', '.join(_RESULT_FIELDS)}.")

    index_name = _fill("Index Name", _param("index_name"), data).strip()
    if not index_name and operation != "LIST_INDICES":
        raise ValueError(f"Index Name is empty. {operation} needs the index to act on.")

    # Everything an operation needs is checked here, before the connection.
    if operation == "SEARCH":
        query = _build_query(data, _param("search_fields"))
        size = _result_count()
    elif operation == "INSERT":
        documents, doc_ids = _documents(data)
    elif operation == "CREATE_INDEX":
        mappings = _optional_object(data, "mappings")
        settings = _optional_object(data, "settings")
    elif operation == "DELETE":
        doc_id = data.get("doc_id")
        query = _optional_object(data, "query_dsl")
        if doc_id in (None, "") and not query:
            raise ValueError("DELETE needs a doc_id or a query_dsl object in request_data.")

    # Forward the incoming data, less the bulky payloads this node consumes.
    passthrough = dict(data)
    for consumed in ("documents", "doc_ids", "query_text", "query_dsl", "mappings", "settings"):
        passthrough.pop(consumed, None)

    es = await perceivo.cluster.elasticsearch.connect()
    perceivo.log.info(f"Elasticsearch: {operation}", operation=operation, index_name=index_name)

    if operation == "SEARCH":
        response = await es.search(index=index_name, query=query, size=size)
        results, total = _hits(response)
        result = {
            **passthrough,
            "operation": operation,
            "index_name": index_name,
            "results": results,
            "total": total,
            "index_missing": bool(response.get("_perceivo_index_missing")),
        }
    elif operation == "INSERT":
        report = await es.bulk_index(index=index_name, documents=documents, doc_ids=doc_ids)
        failed = int(report.get("error_count") or 0)
        if failed:
            raise RuntimeError(
                f"Elasticsearch rejected {failed} of {len(documents)} documents for index "
                f"{index_name!r}: {report.get('errors')}"
            )
        result = {
            **passthrough,
            "operation": operation,
            "index_name": index_name,
            "insert_count": int(report.get("success_count") or 0),
        }
    elif operation == "CREATE_INDEX":
        await es.create_index(name=index_name, mappings=mappings, settings=settings)
        result = {**passthrough, "operation": operation, "index_name": index_name}
    elif operation == "DELETE":
        if doc_id not in (None, ""):
            deleted = 1 if await es.delete_document(index=index_name, doc_id=str(doc_id)) else 0
        else:
            deleted = int(await es.delete_by_query(index=index_name, query=query))
        result = {**passthrough, "operation": operation, "index_name": index_name, "deleted": deleted}
    elif operation == "LIST_INDICES":
        indices = sorted(await es.list_indices())
        result = {**passthrough, "operation": operation, "index_name": index_name, "indices": indices}
    else:
        await es.delete_index(index_name)
        result = {**passthrough, "operation": operation, "index_name": index_name}

    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data={field: result[field] for field in _RESULT_FIELDS[operation]},
            mime_type="application/json",
        ),
        response_data=result,
    )
